args.content:
PREFIX wikidata: <http://www.wikidata.org/schemas/structured-data/>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>

SELECT ?poi ?label ?coord
WHERE {
  {
    ?poi a wikidata:PointOfInterest ;
          wikidata:city wikidata:City ;
          wikidata:country wikidata:Country .
  }
  ?poi wikidata:city wikidata:cityName ?cityLabel .
  ?poi wikidata:country wikidata:countryName ?countryLabel .
  ?poi wikidata:coord .
}
ORDER BY ?poi ?label

